import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.mrTIYZc5.js";const g=JSON.parse('{"title":"What is DSO?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-dso.md","filePath":"guide/what-is-dso.md"}'),s={name:"guide/what-is-dso.md"};function i(n,e,l,c,d,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="what-is-dso" tabindex="-1">What is DSO? <a class="header-anchor" href="#what-is-dso" aria-label="Permalink to &quot;What is DSO?&quot;">​</a></h1><p><strong>Docker Secret Operator (DSO)</strong> is an event-driven secret lifecycle manager for Docker. It provides a native mechanism to synchronize, inject, and rotate secrets from enterprise vaults (AWS, Azure, HashiCorp Vault) or a local encrypted vault directly into containerized workloads.</p><p>DSO is designed to eliminate the risks associated with static secret management, specifically targeting <strong>Secret Proliferation</strong> (credentials left in images, <code>.env</code> files, or host storage) and <strong>Secret Drift</strong> (stale credentials in running containers).</p><h2 id="the-core-design-dual-mode-execution" tabindex="-1">The Core Design: Dual-Mode Execution <a class="header-anchor" href="#the-core-design-dual-mode-execution" aria-label="Permalink to &quot;The Core Design: Dual-Mode Execution&quot;">​</a></h2><p>DSO v3.2 introduces <strong>Dual-Mode Execution</strong>, allowing teams to use the same secure workflow from local development to production.</p><ul><li><strong>Local Mode</strong>: Uses an AES-256-GCM encrypted local vault. Perfect for development and air-gapped environments.</li><li><strong>Cloud Mode</strong>: Connects to high-assurance vaults like AWS Secrets Manager or Azure Key Vault using machine identity.</li></ul><hr><h2 id="core-pillars" tabindex="-1">Core Pillars <a class="header-anchor" href="#core-pillars" aria-label="Permalink to &quot;Core Pillars&quot;">​</a></h2><ul><li><strong>Zero-Persistence</strong>: Secrets are stored in-process RAM and injected into <code>tmpfs</code>. They never touch the host&#39;s physical disk as plaintext.</li><li><strong>Event-Driven</strong>: Immediate response to secret rotation in the vault or container restarts via the Docker event stream.</li><li><strong>Docker-Native</strong>: Built to work with Docker Engine and Docker Compose, requiring no custom entrypoints or sidecars.</li><li><strong>Least Privilege</strong>: DSO leverages machine-identity-based access and secure Unix sockets.</li></ul><h2 id="why-dso" tabindex="-1">Why DSO? <a class="header-anchor" href="#why-dso" aria-label="Permalink to &quot;Why DSO?&quot;">​</a></h2><p>While Kubernetes has mature secret operators, the Docker ecosystem has historically lacked a professional-grade alternative to insecure <code>.env</code> files or manual injection. DSO fills this gap by bringing enterprise-grade secret orchestration to teams running Docker on-premise, on the edge, or in standard cloud instances without the overhead of a full orchestration layer.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/design-principles.html">Design Principles</a></strong>: Understand the philosophy behind the project.</li><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Deep dive into the Watcher, Reloader, and Streamer.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: How we protect secrets from host-level compromise.</li><li><strong><a href="/docs/guide/getting-started.html">Quickstart</a></strong>: Get running in under 2 minutes.</li></ul>',13)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
